<template>
	<view class="container">
		<!-- Logo区域 -->
		<view class="logo-section">
			<image class="logo" src="/static/mynewlogo.png" mode="aspectFit"></image>
			<text class="app-name">陪诊师端</text>
			<text class="slogan">专业陪诊，贴心服务</text>
		</view>
		
		<!-- 登录表单 -->
		<view class="login-form">
			<view class="input-group">
				<view class="input-item">
					<image class="input-icon" src="/static/ren_1.png" mode="aspectFit"></image>
					<input 
						class="input-field" 
						v-model="loginForm.phone" 
						type="number" 
						placeholder="请输入手机号" 
						maxlength="11"
					/>
				</view>
				
				<view class="input-item">
					<image class="input-icon" src="/static/sous.png" mode="aspectFit"></image>
					<input 
						class="input-field" 
						v-model="loginForm.code" 
						type="number" 
						placeholder="请输入验证码" 
						maxlength="6"
					/>
					<button 
						class="code-btn" 
						:disabled="codeDisabled" 
						@click="sendCode"
					>
						{{ codeText }}
					</button>
				</view>
			</view>
			
			<!-- 登录按钮 -->
			<button class="login-btn" @click="login" :disabled="!canLogin">登录</button>
			
			<!-- 协议 -->
			<view class="agreement">
				<checkbox-group @change="onAgreementChange">
					<label class="agreement-item">
						<checkbox :checked="agreed" color="#4A90E2" />
						<text class="agreement-text">
							我已阅读并同意
							<text class="link" @click="showAgreement('user')">《用户协议》</text>
							和
							<text class="link" @click="showAgreement('privacy')">《隐私政策》</text>
						</text>
					</label>
				</checkbox-group>
			</view>
		</view>
		
		<!-- 其他登录方式 -->
		<view class="other-login" v-if="showWechatLogin">
			<view class="divider">
				<text>其他登录方式</text>
			</view>
			<view class="login-methods">
				<button 
					class="wechat-login-btn" 
					open-type="getPhoneNumber" 
					@getphonenumber="onGetPhoneNumber"
					:disabled="!agreed"
				>
					<image class="method-icon" src="/static/wechat-icon.png" mode="aspectFit"></image>
					<text class="method-text">微信一键登录</text>
				</button>
				<view class="wechat-tip" v-if="!agreed">
					<text>请先同意用户协议和隐私政策</text>
				</view>
			</view>
		</view>
		
		<!-- 非微信环境提示 -->
		<view class="env-tip" v-if="!showWechatLogin">
			<text>当前环境不支持微信登录，请使用手机号登录</text>
		</view>
	</view>
</template>

<script setup>
import { ref, computed, onMounted } from 'vue'

// 响应式数据
const loginForm = ref({
	phone: '',
	code: ''
})

const agreed = ref(false)
const codeDisabled = ref(false)
const codeCountdown = ref(0)
const codeText = ref('获取验证码')
const isWechatEnv = ref(false) // 是否为微信环境

// 计算属性
const canLogin = computed(() => {
	return loginForm.value.phone.length === 11 && 
		   loginForm.value.code.length === 6
})

// 检查是否显示微信登录
const showWechatLogin = computed(() => {
	return isWechatEnv.value
})

// 页面初始化
onMounted(() => {
	checkEnvironment()
	checkLoginStatus()
})

// 检查运行环境
const checkEnvironment = () => {
	// 检查是否为微信小程序环境
	// #ifdef MP-WEIXIN
	isWechatEnv.value = true
	console.log('当前环境：微信小程序')
	// #endif
	
	// #ifndef MP-WEIXIN
	isWechatEnv.value = false
	console.log('当前环境：非微信小程序')
	// #endif
}

// 检查登录状态
const checkLoginStatus = () => {
	const isLoggedIn = uni.getStorageSync('isLoggedIn')
	const userInfo = uni.getStorageSync('userInfo')
	
	if (isLoggedIn && userInfo) {
		console.log('用户已登录，跳转到首页')
		uni.reLaunch({
			url: '/pages/index/index'
		})
	}
}

// 方法定义
// 发送验证码
const sendCode = () => {
	if (loginForm.value.phone.length !== 11) {
		uni.showToast({
			title: '请输入正确的手机号',
			icon: 'none'
		})
		return
	}
	
	// TODO: 调用发送验证码API
	uni.showToast({
		title: '验证码已发送',
		icon: 'success'
	})
	
	// 开始倒计时
	startCountdown()
}

// 开始倒计时
const startCountdown = () => {
	codeDisabled.value = true
	codeCountdown.value = 60
	
	const timer = setInterval(() => {
		codeCountdown.value--
		codeText.value = `${codeCountdown.value}s后重发`
		
		if (codeCountdown.value <= 0) {
			clearInterval(timer)
			codeDisabled.value = false
			codeText.value = '获取验证码'
		}
	}, 1000)
}

// 登录
const login = () => {
	// 检查是否同意协议
	if (!agreed.value) {
		uni.showModal({
			title: '提示',
			content: '请先阅读并同意《用户协议》和《隐私政策》',
			showCancel: false,
			confirmText: '确定'
		})
		return
	}
	
	// 检查手机号和验证码
	if (loginForm.value.phone.length !== 11) {
		uni.showToast({
			title: '请输入正确的手机号',
			icon: 'none'
		})
		return
	}
	
	if (loginForm.value.code.length !== 6) {
		uni.showToast({
			title: '请输入6位验证码',
			icon: 'none'
		})
		return
	}
	
	uni.showLoading({
		title: '登录中...'
	})
	
	// TODO: 调用登录API
	setTimeout(() => {
		uni.hideLoading()
		uni.showToast({
			title: '登录成功',
			icon: 'success'
		})
		
		// 跳转到首页
		setTimeout(() => {
			uni.reLaunch({
				url: '/pages/index/index'
			})
		}, 1500)
	}, 2000)
}

// 微信获取手机号
const onGetPhoneNumber = (e) => {
	console.log('获取手机号回调:', e.detail)
	
	// 检查是否同意协议
	if (!agreed.value) {
		uni.showToast({
			title: '请先同意用户协议和隐私政策',
			icon: 'none'
		})
		return
	}
	
	if (e.detail.errMsg === 'getPhoneNumber:ok') {
		// 用户同意授权
		const { encryptedData, iv } = e.detail
		
		if (!encryptedData || !iv) {
			uni.showModal({
				title: '授权失败',
				content: '获取授权信息失败，请重试',
				showCancel: false,
				confirmText: '确定'
			})
			return
		}
		
		// 先获取微信登录code
		uni.login({
			provider: 'weixin',
			success: (loginRes) => {
				console.log('微信登录结果:', loginRes)
				if (loginRes.code) {
					// 处理微信登录
					processWechatLogin(loginRes.code, encryptedData, iv)
				} else {
					uni.showModal({
						title: '登录失败',
						content: '获取登录凭证失败，请重试',
						showCancel: false,
						confirmText: '确定'
					})
				}
			},
			fail: (err) => {
				console.error('微信登录失败:', err)
				uni.showModal({
					title: '登录失败',
					content: '微信登录失败，请检查网络后重试',
					showCancel: true,
					cancelText: '取消',
					confirmText: '重试',
					success: (res) => {
						if (res.confirm) {
							// 用户选择重试
							onGetPhoneNumber(e)
						}
					}
				})
			}
		})
	} else if (e.detail.errMsg === 'getPhoneNumber:fail user deny') {
		// 用户拒绝授权
		uni.showModal({
			title: '授权提示',
			content: '需要授权手机号才能使用微信一键登录功能，您也可以选择手机号验证码登录',
			showCancel: true,
			cancelText: '取消',
			confirmText: '重新授权',
			success: (res) => {
				if (res.confirm) {
					// 用户选择重新授权，但无法直接重新触发，只能提示
					uni.showToast({
						title: '请点击微信一键登录按钮重新授权',
						icon: 'none',
						duration: 3000
					})
				}
			}
		})
	} else {
		// 其他错误
		console.error('获取手机号失败:', e.detail)
		uni.showModal({
			title: '授权失败',
			content: '授权过程中出现错误，请重试',
			showCancel: true,
			cancelText: '取消',
			confirmText: '重试',
			success: (res) => {
				if (res.confirm) {
					uni.showToast({
						title: '请重新点击微信一键登录',
						icon: 'none'
					})
				}
			}
		})
	}
}

// 处理微信登录
const processWechatLogin = async (code, encryptedData, iv) => {
	uni.showLoading({
		title: '登录中...'
	})
	
	try {
		// TODO: 调用后端API解密手机号
		// 实际项目中应该调用真实的后端API
		// const response = await uni.request({
		//     url: 'https://your-api.com/auth/wechat-login',
		//     method: 'POST',
		//     data: {
		//         code,
		//         encryptedData,
		//         iv
		//     }
		// })
		
		// 模拟API调用延迟
		await new Promise(resolve => setTimeout(resolve, 2000))
		
		// 模拟随机成功/失败（用于测试错误处理）
		const isSuccess = Math.random() > 0.1 // 90%成功率
		
		if (!isSuccess) {
			throw new Error('服务器处理失败')
		}
		
		uni.hideLoading()
		
		// 模拟登录成功
		uni.showToast({
			title: '登录成功',
			icon: 'success'
		})
		
		// 模拟存储用户信息
		const userInfo = {
			nickName: '微信用户',
			avatarUrl: '/static/user-placeholder.png',
			phone: '138****8888', // 实际应该是解密后的真实手机号
			loginType: 'wechat',
			token: 'mock_token_' + Date.now(),
			loginTime: new Date().toISOString()
		}
		
		uni.setStorageSync('userInfo', userInfo)
		uni.setStorageSync('isLoggedIn', true)
		
		// 跳转到首页
		setTimeout(() => {
			uni.reLaunch({
				url: '/pages/index/index'
			})
		}, 1500)
		
	} catch (error) {
		uni.hideLoading()
		console.error('微信登录处理失败:', error)
		
		// 根据错误类型显示不同提示
		let errorMessage = '登录失败，请重试'
		if (error.message.includes('网络')) {
			errorMessage = '网络连接失败，请检查网络后重试'
		} else if (error.message.includes('服务器')) {
			errorMessage = '服务器繁忙，请稍后重试'
		} else if (error.message.includes('授权')) {
			errorMessage = '授权信息无效，请重新授权'
		}
		
		uni.showModal({
			title: '登录失败',
			content: errorMessage,
			showCancel: true,
			cancelText: '取消',
			confirmText: '重试',
			success: (res) => {
				if (res.confirm) {
					// 用户选择重试，可以重新触发登录流程
					console.log('用户选择重试登录')
				}
			}
		})
	}
}

// 协议变更
const onAgreementChange = (e) => {
	agreed.value = e.detail.value.length > 0
}

// 显示协议
const showAgreement = (type) => {
	const title = type === 'user' ? '用户协议' : '隐私政策'
	uni.showToast({
		title: `${title}页面开发中`,
		icon: 'none'
	})
}
</script>

